ret = 0;
ret.x = tex2d(sampler_fw_main,uv - dz).x - 0.0 - (GetBlur3(uv).x-GetBlur1(uv+dz).x) ;
dz = -vec2(dx.y,dy.y)*(vec2(1.0)/uTexSize);
ret.y = tex2d(sampler_fw_main,uv - dz).y - 0.06 - (GetBlur2(uv).y-GetBlur1(uv+dz).y)*1.3 ;
float zoom = 1.8-(audioLowSmooth-audioHighSmooth)*0.015;
vec2 cntr = vec2( 0.0 , 0.0 );
vec2 c = vec2(0.28,0.4);
vec2 my_uv2 = (uv_orig-0.5-cntr)*zoom; // using uv_orig here - no contortion to the nice julia island
my_uv2 = vec2(my_uv2.x*my_uv2.x - my_uv2.y*my_uv2.y, 2.0 * my_uv2.x*my_uv2.y) + c; // u -> u^2 + c
uv = my_uv2;
d = (vec2(1.0)/uTexSize) * 4.0;
dx = ( 2.0 * GetBlur1(uv+vec2( 1.0 , 0.0 )*d) - 2.0*GetBlur1(uv-vec2( 1.0 , 0.0 )*d).xy );
dy = ( 2.0 * GetBlur1(uv+vec2( 0.0 , 1.0 )*d) - 2.0*GetBlur1(uv-vec2( 0.0 , 1.0 )*d).xy );
dz = vec2(dx.z,dy.z)*(vec2(1.0)/uTexSize) * 1.0;
ret.z = GetPixel(clamp01(my_uv2+dz)).z - 0.014;
}
  fragColor = vec4(ret, 1.0);
