vec2 bipolar_uv = uv_bipolar(rotate_uv,vec2( 0.0 ,0.5),vec2( 1.0 ,0.5), 2.0 , 0.3, vec2(q11,q12));
vec2 mirror_uv = 0.5 + (0.5 - abs( fract( bipolar_uv * 0.5 ) * 2.0 - 1.0 ));
vec2 d = (vec2(1.0)/uTexSize) * 3.0;
vec3 dx = ( 2.0 * GetBlur1(mirror_uv+vec2( 1.0 , 0.0 )*d) - 2.0*GetBlur1(mirror_uv-vec2( 1.0 , 0.0 )*d) );
vec3 dy = ( 2.0 * GetBlur1(mirror_uv+vec2( 0.0 , 1.0 )*d) - 2.0*GetBlur1(mirror_uv-vec2( 0.0 , 1.0 )*d) );
mirror_uv += vec2(dx.x,dy.x)*(vec2(1.0)/uTexSize) * 4.0;
vec3 aura = pow(hue_shader, 4.0 )*1.4;
vec3 glow = 3;
vec3 blob = vec3( 1.0 ,0.75, 0.0 ) * 0.0;
vec2 uv_red = mirror_uv;
ret = mix(ret, 1.0 ,(GetBlur1(uv_red).x)*(1.0 - GetBlur2(uv_red).x)*aura);
ret = mix(blob, ret, GetPixel(uv_red).x);
ret += (1.0 - GetPixel(uv_red).x)*GetBlur1(uv_red).x*glow;
mirror_uv-= vec2(dx.x,dy.x)*(vec2(1.0)/uTexSize) * 24.0;
dx = ( 2.0 * GetBlur1(mirror_uv+vec2( 1.0 , 0.0 )*d) - 2.0*GetBlur1(mirror_uv-vec2( 1.0 , 0.0 )*d) );
dy = ( 2.0 * GetBlur1(mirror_uv+vec2( 0.0 , 1.0 )*d) - 2.0*GetBlur1(mirror_uv-vec2( 0.0 , 1.0 )*d) );
vec2 dz = +vec2(-dx.y,dy.y)*0.25;
vec3 bg = mix(vec3( 1.0 ,0.7,0.2),vec3(0.15, 0.0 ,0.5),mirror_uv.x*0.8 - mirror_uv.y + 0.75+dz.x+dz.y-0.1)*(GetPixel(mirror_uv).y);
ret = mix(ret, 1.0 ,bg);
mirror_uv = uv_rotate(0.5 + (uvo-0.5)*uAspect.wz, 0.5, q3, q4, 1.0 ).yx;
d = (vec2(1.0)/uTexSize);
dx = ( 2.0 * GetPixel(mirror_uv+vec2( 1.0 , 0.0 )*d) - 2.0*GetPixel(mirror_uv-vec2( 1.0 , 0.0 )*d) );
dy = ( 2.0 * GetPixel(mirror_uv+vec2( 0.0 , 1.0 )*d) - 2.0*GetPixel(mirror_uv-vec2( 0.0 , 1.0 )*d) );
dz = -vec2(dx.z,dy.z);
ret = vec3( 1.0 ) - mix(ret,vec3(0.9,0.9, 1.0),1.0 - GetPixel(mirror_uv+dz).z) ;
}
  fragColor = vec4(ret, 1.0);
}

